const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(104.238631, 40.923221);
  const geometry = point.buffer(50 * 1000); // 50 km radius in meters

  const date2019_start = '2019-02-01';
  const date2019_end = '2019-02-28'; // 2019 was not a leap year
  const date2020_start = '2020-02-01';
  const date2020_end = '2020-02-29'; // 2020 was a leap year

  const bandName = 'particulate_matter_pm2p5';
  const scale = 5000; // Use a reasonable scale to avoid memory issues and ensure timely execution

  // Function to process data for a given period
  async function getPm25Mean(startDate, endDate, geom, year) {
    let collection = ee.ImageCollection('COPERNICUS/CAMS/NRT')
      .filterDate(startDate, endDate)
      .filterBounds(geom)
      .select(bandName);

    const collectionSize = await collection.size().getInfo();

    if (collectionSize === 0) {
      console.log(`No CAMS NRT images found for ${year} (${startDate} to ${endDate}).`);
      return { value: null, status: 'C1' };
    }

    // Calculate the mean image over the period
    let meanImage = collection.mean();

    // Reduce the mean image to get the average PM2.5 value over the geometry
    const result = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (result === null || isNaN(result)) {
      console.log(`Calculation of mean PM2.5 failed for ${year}. Result is null/NaN.`);
      return { value: null, status: 'C3' };
    }

    // Optional: Check for valid pixels, though CAMS NRT usually doesn't have 0 valid pixels after filtering
    // This is more relevant for optical imagery with heavy cloud masking
    // For CAMS, if result is not null, it implies valid data.

    return { value: result, status: 'OK', count: collectionSize };
  }

  // Get PM2.5 for 2019
  const result2019 = await getPm25Mean(date2019_start, date2019_end, geometry, '2019');
  if (result2019.status !== 'OK') {
    console.log(`<answer>${result2019.status}</answer>`);
    return;
  }

  // Get PM2.5 for 2020
  const result2020 = await getPm25Mean(date2020_start, date2020_end, geometry, '2020');
  if (result2020.status !== 'OK') {
    console.log(`<answer>${result2020.status}</answer>`);
    return;
  }

  const pm25_2019 = result2019.value;
  const pm25_2020 = result2020.value;
  const images_2019 = result2019.count;
  const images_2020 = result2020.count;

  // 5. Validation & Final Answer
  console.log(`February 2019 PM2.5: ${pm25_2019.toFixed(2)} µg/m³ (Images: ${images_2019})`);
  console.log(`February 2020 PM2.5: ${pm25_2020.toFixed(2)} µg/m³ (Images: ${images_2020})`);

  if (pm25_2020 > pm25_2019) {
    console.log("<answer>A</answer>"); // PM2.5 level was higher in Feb 2020
  } else {
    console.log("<answer>B</answer>"); // PM2.5 level was not higher in Feb 2020
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
